import java.util.Scanner;

public class HeadacheCure {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Welcome to the Headache Cure Program!");
        System.out.print("Please enter the severity level of your headache (1-5): ");
        int headacheSeverity = scanner.nextInt();

        if (headacheSeverity == 1) {
            System.out.println("Your headache seems mild.");
        } else if (headacheSeverity == 2) {
            System.out.println("Your headache may require some attention.");
        } else if (headacheSeverity == 3) {
            System.out.println("Your headache could be quite uncomfortable.");
        } else if (headacheSeverity == 4) {
            System.out.println("Your headache is likely causing significant discomfort.");
        } else if (headacheSeverity == 5) {
            System.out.println("Your headache is very severe and requires immediate medical attention.");
        }

        scanner.close();
    }
}
